patch_result.patch:
--- a/arrow/cpp/src/arrow/ipc/metadata_internal.cc
+++ b/arrow/cpp/src/arrow/ipc/metadata_internal.cc
@@ -161,17 +161,28 @@

   const flatbuffers::Vector<int32_t>* fb_type_ids = union_data->typeIds();
   if (fb_type_ids == nullptr) {
-    // TODO validate that children.size() <= 127?
+    if (children.size() > static_cast<size_t>(UnionType::kMaxTypeCode) + 1) {
+      return Status::Invalid("Union type has too many children for int8 type codes: ",
+                             children.size());
+    }
     for (int8_t i = 0; i < static_cast<int8_t>(children.size()); ++i) {
       type_codes.push_back(i);
     }
   } else {
     for (int32_t id : (*fb_type_ids)) {
-      // TODO(wesm): can these values exceed 127?
+      if (id < 0 || id > UnionType::kMaxTypeCode) {
+        return Status::Invalid("Union type id out of range: ", id,
+                               ", expected [0, ", UnionType::kMaxTypeCode, "]");
+      }
       type_codes.push_back(static_cast<int8_t>(id));
     }
   }

+  if (type_codes.size() != children.size()) {
+    return Status::Invalid("Union type ids length does not match number of children: ",
+                           type_codes.size(), " != ", children.size());
+  }
+
   *out = union_(children, type_codes, mode);
   return Status::OK();
 }

